macro_rules! deflateSetHeader {
    () => {
        # [doc = " Provides gzip header information for when a gzip stream is requested by [`deflateInit2_`]."] # [doc = ""] # [doc = " [`deflateSetHeader`] may be called after [`deflateInit2_`] or [`deflateReset`]) and before the first call of [`deflate`]. The header's `text`, `time`, `os`, `extra`, `name`, and `comment` fields in the provided [`gz_header`] structure are written to the gzip header (xflag is ignored — the extra flags are set according to the compression level)."] # [doc = ""] # [doc = " The caller must assure that, if not `NULL`, `name` and `comment` are terminated with a zero byte, and that if `extra` is not NULL, that `extra_len` bytes are available there."] # [doc = " If `hcrc` is true, a gzip header crc is included."] # [doc = ""] # [doc = " If [`deflateSetHeader`] is not used, the default gzip header has text false, the time set to zero, and os set to the current operating system, with no extra, name, or comment fields. The gzip header is returned to the default state by [`deflateReset`]."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_STREAM_ERROR`] if the stream state was inconsistent"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `strm` is `NULL`"] # [doc = "     - `strm` satisfies the requirements of `&mut *strm` and was initialized with [`deflateInit_`] or similar"] # [doc = " * Either"] # [doc = "     - `head` is `NULL`"] # [doc = "     - `head` satisfies the requirements of `&mut *head` and satisfies the following:"] # [doc = "         - `head.extra` is `NULL` or is readable for at least `head.extra_len` bytes"] # [doc = "         - `head.name` is `NULL` or satisfies the requirements of [`core::ffi::CStr::from_ptr`]"] # [doc = "         - `head.comment` is `NULL` or satisfies the requirements of [`core::ffi::CStr::from_ptr`]"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (deflateSetHeader))] pub unsafe extern "C-unwind" fn deflateSetHeader (strm : * mut z_stream , head : gz_headerp) -> c_int { let Some (stream) = (unsafe { DeflateStream :: from_stream_mut (strm) }) else { return ReturnCode :: StreamError as _ ; } ; let header = unsafe { head . as_mut () } ; zlib_rs :: deflate :: set_header (stream , header) as _ }
    };
}

deflateSetHeader!()